{"file_path":"src/path.js","content":"/** Helpers for building and comparing the dotted/indexed paths used in
 * error messages and in the `keys` output. */

export function nameToken(text) {
  return { kind: 'name', text }
}

export function indexToken(i) {
  return { kind: 'index', i }
}

export function joinPath(tokens) {
  let out = ''
  for (const t of tokens) {
    if (t.kind === 'name') {
      out += (out.length ? '.' : '') + t.text
    } else {
      out += `[${t.i}]`
    }
  }
  return out
}

/** Compares two strings by Unicode code point, ascending. */
export function compareCodePoint(a, b) {
  const ac = Array.from(a)
  const bc = Array.from(b)
  const len = Math.min(ac.length, bc.length)
  for (let i = 0; i < len; i++) {
    const ca = ac[i].codePointAt(0)
    const cb = bc[i].codePointAt(0)
    if (ca !== cb) return ca - cb
  }
  return ac.length - bc.length
}

export function sortedKeys(map) {
  return [...map.keys()].sort(compareCodePoint)
}
"}

